ALTER TABLE "deliveries" ADD CONSTRAINT "deliveries_assigned_state_consistent" CHECK ("deliveries"."status" NOT IN ('assigned', 'in_transit', 'completed') OR ("deliveries"."assigned_user_id" IS NOT NULL AND "deliveries"."assigned_at" IS NOT NULL AND "deliveries"."assigned_by" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "deliveries" ADD CONSTRAINT "deliveries_in_transit_state_consistent" CHECK ("deliveries"."status" NOT IN ('in_transit', 'completed') OR ("deliveries"."dispatched_at" IS NOT NULL AND "deliveries"."dispatched_by" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "deliveries" ADD CONSTRAINT "deliveries_completed_state_consistent" CHECK ("deliveries"."status" <> 'completed' OR ("deliveries"."completed_at" IS NOT NULL AND "deliveries"."completed_by" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "deliveries" ADD CONSTRAINT "deliveries_cancelled_state_consistent" CHECK ("deliveries"."status" <> 'cancelled' OR ("deliveries"."cancelled_at" IS NOT NULL AND "deliveries"."cancelled_by" IS NOT NULL));
